#### Production NGINX Directives #066
In edge routing configuration 066, upstream connectivity and security isolation are prioritized.

```nginx
# NGINX configuration block for nginx_event_worker_model #066
upstream backend_cluster_066 {
    least_conn;
    server 10.0.66.10:8080 max_fails=3 fail_timeout=10s;
    server 10.0.66.11:8080 max_fails=3 fail_timeout=10s;
    keepalive 32;
}

server {
    listen 443 ssl http2;
    server_name service-066.enterprise.internal;
    ssl_certificate /etc/nginx/ssl/service-066.crt;
    ssl_certificate_key /etc/nginx/ssl/service-066.key;

    location /api/v1/ {
        proxy_pass http://backend_cluster_066;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_read_timeout 36s;
    }
}
```

