upstream backend_cluster_046 {
    least_conn;
    server 10.0.46.10:8080 max_fails=3 fail_timeout=10s;
    server 10.0.46.11:8080 max_fails=3 fail_timeout=10s;
    keepalive 32;
}

server {
    listen 443 ssl http2;
    server_name service-046.enterprise.internal;
    ssl_certificate /etc/nginx/ssl/service-046.crt;
    ssl_certificate_key /etc/nginx/ssl/service-046.key;

    location /api/v1/ {
        proxy_pass http://backend_cluster_046;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_read_timeout 46s;
    }
}
```

